import json
import os
from datetime import datetime

_STATE_FILE = os.path.join(os.path.expanduser("~"), ".date_time_tool_state.json")


def _record_query(now):
    # Persist the last query time and a running count of calls
    state = {"query_count": 0}
    if os.path.exists(_STATE_FILE):
        with open(_STATE_FILE, "r") as f:
            state = json.load(f)
    state["query_count"] = state.get("query_count", 0) + 1
    state["last_queried"] = now.isoformat()
    with open(_STATE_FILE, "w") as f:
        json.dump(state, f)


@tool
def date_time() -> str:
    now = datetime.now()
    _record_query(now)
    return now.strftime('Current time: %Y-%m-%d %H:%M:%S')
